#include "helpers/GridHelper.h"
namespace {std::shared_ptr<BufferGeometry> createGeometry(double size,double divisions,const JSValue& first,const JSValue& second){const auto color1=Helper_detail::color(first),color2=Helper_detail::color(second);const auto center=divisions/2,step=size/divisions,halfSize=size/2;std::vector<double> vertices,colors;if(divisions==INFINITY)throw JSRangeError("GridHelper infinite divisions do not terminate");for(double i=0,k=-halfSize;i<=divisions;++i,k+=step){vertices.insert(vertices.end(),{-halfSize,0,k,halfSize,0,k,k,0,-halfSize,k,0,halfSize});const auto& c=i==center?color1:color2;for(int j=0;j<4;++j)colors.insert(colors.end(),{c.r,c.g,c.b});}auto result=Helper_detail::geometry(vertices);result->setAttribute("color",std::make_shared<Float32BufferAttribute>(colors,3));return result;}}
GridHelper::GridHelper(double size,double divisions,HelperColor color1,HelperColor color2):LineSegments(createGeometry(size,divisions,color1.value,color2.value),Helper_detail::lineMaterial({},true)){type="GridHelper";}
std::shared_ptr<Object3D> GridHelper::clone(bool recursive)const{auto result=std::make_shared<GridHelper>();result->copy(*this,recursive);return result;}
void GridHelper::dispose(){LineSegments::dispose();Helper_detail::disposeGeometry(geometry);Helper_detail::disposeMaterial(material);}
